def previous_done():
    """Job 1 first; job 2 after job 1's result is fetched (or its end recorded)."""
    n = int(JOB[3:])
    if n == 1:
        return True, "the first job"
    prev = f"job{n - 1}"
    if (HERE / f"results-t18-{prev}-counts.json").exists() or (HERE / f"failed-t18-{prev}.json").exists():
        return True, f"{prev}'s result is fetched or its end recorded"
    d = recorded(f"decision-t18-{prev}.json")
    if d and not d["decision"]["runs"]:
        return False, f"{prev}'s decision says it does not run"
    return False, f"{prev}'s result is not fetched"


