def fetch(job_id, M_):
    svc = service()
    j = svc.job(job_id)
    st = str(j.status())
    log(f"{JOB} job {job_id} status {st}")
    sub = json.loads((HERE / f"submit-t18-{JOB}.json").read_text())
    assert sub["job_id"] == job_id
    if any(f in st for f in ("ERROR", "CANCELLED")):
        try:
            msg = scrub(j.error_message())
        except Exception as e:
            msg = type(e).__name__
        rec = {"job": JOB, "job_id": job_id, "status": "ERROR" if "ERROR" in st else "CANCELLED", "status_raw": st, "recorded_utc": now(),
               "error_message": msg, "note": "recorded and never resubmitted (t18-rule.md section 2)"}
        (HERE / f"failed-t18-{JOB}.json").write_text(json.dumps(rec, indent=1))
        record_stamp(svc.backend(BACKEND), f"{JOB} after final status", st)
        sys.exit(f"job ended {st}; recorded in failed-t18-{JOB}.json; never resubmitted")
    if "DONE" not in st:
        sys.exit("not done; nothing written")
    res = j.result()
    counts = [res[k].data.c.get_counts() for k in range(len(sub["labels"]))]
    try:
        ex = spans_record(res)
    except Exception as e:
        ex = {"present": False, "error": type(e).__name__}
    mt = j.metrics()
    use = mt.get("usage") or {}
    for x in use.get("details", []):
        (x.get("metric") or {}).pop("id", None)
    try:
        opts = j.inputs.get("options")
    except Exception:
        opts = None
    after = record_stamp(svc.backend(BACKEND), f"{JOB} after fetch", st)
    out = {"meta": M_, "job": JOB, "job_id": job_id, "backend": BACKEND, "qubit": QUBIT, "dt_s": sub["dt_s"], "waits": sub["waits"],
           "timestamps": mt.get("timestamps"), "usage": use, "job_options_as_recorded_by_ibm": opts,
           "calibration_at_submission": sub["calibration_at_submission"], "calibration_after_fetch": after["stamp_raw"],
           "fetched_utc": after["utc"], "labels": sub["labels"], "shots": sub["shots"], "counts": counts,
           "result_length_equals_positions": len(res) == len(sub["labels"]), "execution_metadata": ex}
    (HERE / f"results-t18-{JOB}-counts.json").write_text(json.dumps(out, default=str))
    log(f"{JOB} fetched {len(counts)} positions; execution metadata saved {ex.get('present')} ({len(ex.get('execution_spans', []))} spans); "
        f"recorded machine time {use.get('qpu_charge_time_seconds')} s; calibration after {after['stamp_raw']}; options by IBM {opts}")


# --------------------------------------------------------------------------- the dry run
def dryrun(M_):
    """The build and every check on FakeFez, offline: nothing submitted."""
    from qiskit_ibm_runtime.fake_provider import FakeFez
    b = FakeFez()
    circ, info, recs, circs, labels, shots, lim, waits, oc, ok = built(b)
    smp, sopt, sgood = sampler_for(b)
    rec = {"meta": M_, "backend": b.name, "dt_s": b.dt, "granularity": getattr(b.target, "granularity", 1) or 1, "summary": summary(recs),
           "checks": recs, "order_checks": oc, "limits": lim, "sampler_options": sopt, "waits": waits, "n_positions": len(circs), "shots": sum(shots),
           "first_labels": labels[:6], "digests": digests(circ), "estimate": estimate(sum(shots)), "all_pass": ok and sgood}
    (HERE / "dryrun-t18.json").write_text(json.dumps(rec, indent=1, default=str))
    log(f"dry run on {b.name}: {summary(recs)}; order {oc['pass']}; {len(circs)} positions, {sum(shots)} shots; limits {lim['within']}; sampler {sopt}; "
        f"scheduled waits equal to requested {all(abs(w['difference_us'][q]) < 1e-9 for w in waits for q in QUADS)}; all {ok and sgood}")
    if not rec["all_pass"]:
        sys.exit("dry run: a check failed")


def main():
    global JOB
    ap = argparse.ArgumentParser()
    ap.add_argument("--job", type=int)
    for f in ("--dryrun", "--decision", "--check", "--submit", "--go"):
        ap.add_argument(f, action="store_true")
    ap.add_argument("--inputs", metavar="RULE_SHA256")
    ap.add_argument("--fetch")
    a = ap.parse_args()
    if a.decision or a.check or a.submit or a.fetch:
        if a.job is None or not 1 <= a.job <= CFG["max_jobs"]:
            sys.exit(f"--job must be 1 to {CFG['max_jobs']}")
    JOB = f"job{a.job}" if a.job else None
    M_ = meta()
    if a.inputs:
        inp = inputs_static(a.inputs)
        old = recorded(inputs_name()) or {}
        if "jobs" in old:
            inp["jobs"] = old["jobs"]
        (HERE / inputs_name()).write_text(json.dumps(inp, indent=1))
        m = inp["manacitra"]
        log(f"inputs: manacitra {m['tag']} at {COMMIT} (tag resolves to {m['tag_resolves_to']}), version string {m['version_string']}, installed equal to the "
            f"archive {m['installed_equals_archive']}; rule sha256 matches {inp['rule']['matches']} ({inp['rule']['size_bytes']} bytes); reused code unchanged {inp['reused_unchanged']}")
        if not (inp["rule"]["matches"] and all(inp["reused_unchanged"].values()) and m["commit_present"] == "commit"
                and m["tag_resolves_to"] == COMMIT and m["installed_equals_archive"]):
            sys.exit("STOP: the rule, the package, the commit or the reused code differs from what the runner prompt names")
    if not a.inputs and not (recorded(inputs_name()) or {}).get("rule", {}).get("matches"):
        sys.exit("STOP: the rule's hash has not been confirmed")
    if a.dryrun:
        dryrun(M_)
    if a.decision:
        write_decision()
    if a.check:
        live(a, M_, True)
    if a.submit:
        live(a, M_, False)
    if a.fetch:
        fetch(a.fetch, M_)


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        raise
    except Exception as e:  # noqa: BLE001  never let a traceback print an identifier
        print(f"{now()} ERROR {type(e).__name__}: {scrub(e)}", flush=True)
        sys.exit(1)

