from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import argparse  # noqa: E402
import hashlib  # noqa: E402
import importlib.util  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import time  # noqa: E402
from datetime import datetime  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402

HERE = Path(__file__).resolve().parent
OUT = HB / "t18"
T15 = HB / "t15"
KEYS = ["job1", "job2"]
FINDING_30 = [  # the three run means exactly as finding 30 states them (ruling 5), on the weight's branch, over six spans
    {"run": "test 11, day 2, jobs 2 and 3", "when_utc": "17 October, 20:01 to 20:06", "mean_duty": 0.330, "sd": 0.020},
    {"run": "test 11, day 3, jobs 2 and 3", "when_utc": "19 October, 04:12 to 04:18", "mean_duty": 0.341, "sd": 0.025},
    {"run": "test 17, job B1", "when_utc": "19 October, 17:10 to 17:12", "mean_duty": 0.313, "sd": 0.024}]
Z_HIGH, Z_LOW = 2.0, 1.0
MID = (1 / 3, 2 / 3)
R15 = None


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00"))


def load_read_t15():
    want = None
    for line in (T15 / "SHA256SUMS").read_text().splitlines():
        parts = line.split()
        if len(parts) == 2 and parts[1] == "read_t15.py":
            want = parts[0]
    now = sha(T15 / "read_t15.py")
    if want is None or now != want:
        sys.exit(f"STOP: read_t15.py's SHA-256 {now} differs from its line in t15/SHA256SUMS ({want})")
    spec = importlib.util.spec_from_file_location("read_t15", T15 / "read_t15.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    mod.HB = HB          # the only change: test 15's hand-back root, pointed at tests/handback/
    mod.OUT = OUT
    return mod, now


# ---------------------------------------------------------------- 0 and 1

def check_hashes():
    rec = {}
    p = OUT / "shots-t18-hashes-before-analysis.txt"
    for line in p.read_text().splitlines():
        parts = line.split()
        if len(parts) >= 2 and len(parts[0]) == 64:
            rec[parts[1]] = parts[0]
    out = {name: {"recorded": h, "now": sha(OUT / name), "equal": sha(OUT / name) == h} for name, h in rec.items()}
    ok = {k: sum(n.startswith(f"shots-t18-{k}") for n in out) == 2 and all(v["equal"] for n, v in out.items() if n.startswith(f"shots-t18-{k}"))
          for k in KEYS}
    return out, ok


def counts_copy_check(key):
    """The published counts file against the record it was copied from."""
    cp = json.loads((OUT / "copies-t18.json").read_text()) if (OUT / "copies-t18.json").exists() else {}
    c = cp.get(key)
    if not c:
        return {"pass": False, "note": "no copy record"}
    now = sha(OUT / f"counts-t18-{key}.json")
    return {"pass": now == c["copied_sha256"], "copied_sha256": c["copied_sha256"], "now": now, "as_fetched_sha256": c["as_fetched_sha256"],
            "removed": c["removed"]}


# ---------------------------------------------------------------- section 5

def record_spans(job):
    wd = job["qubits"]["143"]["waits"]["monitor"]
    q = wd["quadrature_of_record"]
    return wd, q, [s for s in wd["spans"] if q in s]


def span_times(job):
    """Each span's normalized centre t, from the execution record's starts and stops."""
    sp = sorted(job["spans"], key=lambda s: s["start_utc"])
    t0, t1 = ts(sp[0]["start_utc"]), ts(sp[-1]["stop_utc"])
    L = (t1 - t0).total_seconds()
    return {s["span"]: ((ts(s["start_utc"]) - t0).total_seconds() + (ts(s["stop_utc"]) - ts(s["start_utc"])).total_seconds() / 2) / L for s in sp}


def contrast(rows, duty_key="duty", sd_key="sd"):
    """C and its sd from rows of {t, duty, sd}; None if no span centre lies in [1/3, 2/3] or none outside it."""
    mid = [r for r in rows if MID[0] <= r["t"] <= MID[1]]
    oth = [r for r in rows if not (MID[0] <= r["t"] <= MID[1])]
    if not mid or not oth:
        return None
    m_mid = float(np.mean([r[duty_key] for r in mid]))
    m_oth = float(np.mean([r[duty_key] for r in oth]))
    sd_mid = math.sqrt(sum(r[sd_key] ** 2 for r in mid)) / len(mid)
    sd_oth = math.sqrt(sum(r[sd_key] ** 2 for r in oth)) / len(oth)
    C = m_mid - m_oth
    sd = math.hypot(sd_mid, sd_oth)
    return {"C": C, "sd": sd, "C_over_sd": C / sd, "mean_mid": m_mid, "mean_other": m_oth, "sd_mid": sd_mid, "sd_other": sd_oth,
            "mid_spans": [r["span"] for r in mid], "other_spans": [r["span"] for r in oth]}


def wline(t, y, sd):
    t, y, w = np.asarray(t, float), np.asarray(y, float), 1 / np.asarray(sd, float) ** 2
    if len(t) < 3:
        return None
    X = np.stack([np.ones_like(t), t], axis=1)
    G = X.T @ (X * w[:, None])
    a0, b0 = np.linalg.solve(G, X.T @ (w * y))
    se = math.sqrt(np.linalg.inv(G)[1, 1])
    return {"intercept": float(a0), "slope_per_unit_t": float(b0), "slope_sd": se, "slope_over_sd": float(b0) / se}


def middle_job(key, span_rows, n_spans):
    """span_rows: per span {span, t, word, duty, sd, duty_2080, sd_2080, w_branch}. Returns the job's row of the middle test."""
    row = {"job": key, "n_spans": n_spans, "spans": span_rows}
    if n_spans < 3:
        row.update({"contributes": False, "reason": "fewer than three spans"})
        return row
    not_shared = [r["span"] for r in span_rows if r["word"] != "SHARED"]
    if not_shared:
        row.update({"contributes": False, "reason": f"ruling 3: spans {not_shared} are not SHARED, so they carry no telegraph sd"})
        return row
    c = contrast(span_rows)
    if c is None:
        row.update({"contributes": False, "reason": "no span centre in [1/3, 2/3] (or none outside it)"})
        return row
    row.update({"contributes": True, **c})
    c2 = contrast(span_rows, "duty_2080", "sd_2080")
    row["beside_threshold_20_80"] = c2
    row["beside_line_duty_on_t"] = wline([r["t"] for r in span_rows], [r["duty"] for r in span_rows], [r["sd"] for r in span_rows])
    return row


def pooled(rows):
    used = [r for r in rows if r.get("contributes")]
    n = len(used)
    if not n:
        return {"n_contributing_jobs": 0, "Z": None, "word": None, "note": "no job contributes a contrast"}
    Z = sum(r["C_over_sd"] for r in used) / math.sqrt(n)
    word = "MIDDLE HIGH" if Z >= Z_HIGH else ("NOT SEEN" if Z < Z_LOW else "UNDECIDED")
    out = {"n_contributing_jobs": n, "contributing": [r["job"] for r in used], "listed_not_contributing": [(r["job"], r["reason"]) for r in rows if not r.get("contributes")],
           "Z": Z, "word": word}
    u2 = [r["beside_threshold_20_80"] for r in used if r.get("beside_threshold_20_80")]
    if len(u2) == n:
        out["beside_Z_at_threshold_20_80"] = sum(x["C_over_sd"] for x in u2) / math.sqrt(n)
    return out


def span_rows_of(job):
    wd, q, sp = record_spans(job)
    tt = span_times(job)
    rows = []
    for s in sp:
        r = s[q]
        rows.append({"span": s["span"], "t": tt[s["span"]], "word": r.get("word"), "duty": r.get("duty_b"), "sd": r.get("telegraph_sd"),
                     "sd_is_ceiling": r.get("tau_c_ceiling"), "duty_2080": r.get("duty_b_at_threshold_20_80"),
                     "sd_2080": r.get("telegraph_sd_at_threshold_20_80"), "w_branch": s.get("w_branch"), "n_whole_repeats": s.get("n_whole_repeats")})
    return rows, len(job["spans"])


# ---------------------------------------------------------------- the published level changes of this run

def published_from_counts():
    f = json.loads((OUT / "fits-t18-counts.json").read_text())
    pub = {}
    for key, j in f["jobs"].items():
        if "analysis" not in j:
            continue
        wps = {s["span"]: s for s in j["analysis"]["weight_per_span"]}
        pub[key] = [{"spans": x["spans"], "w": [wps[x["spans"][0]]["mean_w"], wps[x["spans"][1]]["mean_w"]], "difference": x["difference"],
                     "error": x["error"], "in_errors": x["in_errors"], "source": "fits-t18-counts.json, level_changes"} for x in j["analysis"]["level_changes"]]
    return pub


# ---------------------------------------------------------------- section 4, beside (ruling 5)

def earlier_monitor_means():
    """The job mean duties of every monitor job at 5.6 us on 17 and 19 October, as their reads recorded them."""
    rows = []
    f15 = json.loads((HB / "t15" / "fits-t15.json").read_text())
    for x in f15["between_jobs_143"]["jobs"]:
        if x["job"] in ("t11-job2", "t11-job3"):
            rows.append({"job": f"test 11 day 2, job {x['job'][-1]}", "date": "17 October", "design": "test 11's monitor, 300 positions, 1,000 shots",
                         "running_utc": x["running_utc"], "job_mean_w_duty": x["job_mean_w_duty"], "job_sd": x["job_sd"], "w_branches": x["w_branches"],
                         "source": "tests/handback/t15/fits-t15.json, between_jobs_143"})
    f16 = json.loads((HB / "t16" / "fits-t16.json").read_text())
    for x in f16["between_jobs"]["jobs"]:
        rows.append({"job": f"test 11 day 3, job {x['job'][-1]}", "date": "19 October", "design": "test 11's monitor, 300 positions, 1,000 shots",
                     "running_utc": x["running_utc"], "job_mean_w_duty": x["job_mean_w_duty"], "job_sd": x["job_sd"], "w_branches": x["w_branches"],
                     "source": "tests/handback/t16/fits-t16.json, between_jobs"})
    f17 = json.loads((HB / "t17" / "fits-t17-shots.json").read_text())
    for k, design in (("B1", "test 17's long monitor, 600 positions, 1,000 shots"), ("A1", "test 12's short monitor, 250 positions, 500 shots"),
                      ("A2", "test 12's short monitor, 250 positions, 500 shots")):
        x = f17["between_jobs_job_rows"][k]
        rows.append({"job": f"test 17, {k}", "date": "19 October", "design": design, "running_utc": x["running_utc"], "job_mean_w_duty": x["job_mean_w_duty"],
                     "job_sd": x["job_sd"], "w_branches": x["w_branches"], "source": "tests/handback/t17/fits-t17-shots.json, between_jobs_job_rows"})
    return rows


def test17_Z():
    f17 = json.loads((HB / "t17" / "fits-t17-shots.json").read_text())
    p = f17["middle_test"]["pooled"]
    return {"Z": p["Z"], "word": p["word"], "n_contributing_jobs": p["n_contributing_jobs"], "source": "tests/handback/t17/fits-t17-shots.json, middle_test.pooled",
            "note": "test 17's Z, set beside with no combined word; this test does not pool with it"}


def this_run_means(out, read):
    jr = out.get("between_jobs_job_rows", {})
    rows, spans_w, spans_b = [], [], []
    for key in read:
        wd, q, sp = record_spans(out["jobs"][key])
        bs = [s[q]["duty_b"] for s in sp]
        ws = [s.get("w_duty") for s in sp]
        spans_w += ws
        spans_b += bs
        x = jr.get(key, {})
        rows.append({"job": key, "n_spans": len(sp), "job_mean_w_duty": float(np.mean(ws)), "job_sd": x.get("job_sd"), "w_branches": sorted({s["w_branch"] for s in sp}),
                     "job_mean_threshold_duty_b": float(np.mean(bs)), "running_utc": x.get("running_utc")})
    run = {"n_spans": len(spans_w), "run_mean_w_duty": float(np.mean(spans_w)) if spans_w else None,
           "run_mean_threshold_duty_b": float(np.mean(spans_b)) if spans_b else None,
           "note": "the mean over every span of the run, as finding 30 takes a run's mean over its spans"}
    if len(read) == 2 and all(r["job_sd"] is not None for r in rows):
        run["run_sd_of_the_mean_of_the_two_job_means"] = math.hypot(rows[0]["job_sd"], rows[1]["job_sd"]) / 2
    return rows, run


def gap_between(read):
    if len(read) != 2:
        return {"note": "not available: two jobs were not read"}
    sp = [json.loads((OUT / f"counts-t18-{k}.json").read_text())["execution_metadata"]["execution_spans"] for k in read]
    stop1 = max(ts(s["stop_utc"]) for s in sp[0])
    start2 = min(ts(s["start_utc"]) for s in sp[1])
    return {"job1_last_span_stop_utc": stop1.isoformat(), "job2_first_span_start_utc": start2.isoformat(), "gap_s": (start2 - stop1).total_seconds(),
            "source": "the execution metadata saved with the counts at fetch"}


# ---------------------------------------------------------------- main

def main():
    global R15
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="fits-t18-shots.json")
    a = ap.parse_args()
    t0 = time.time()
    R15, r15sha = load_read_t15()
    hashes, ok = check_hashes()
    out = {"meta": {"script_sha256": sha(__file__), "read_t15_sha256": r15sha, "computed_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "definitions": "test 15's, by its own code (read_t15.py, unchanged); test 13's whole repeats and quadrature of record",
                    "thresholds": {"SHARED_above": R15.RATIO_SHARED, "INDEPENDENT_below": R15.RATIO_INDEP, "lags": R15.LAGS,
                                   "boundary_words": "NO CHANGE at or under 2, BETWEEN over 2 to 3, CHANGE over 3 combined telegraph sd",
                                   "middle_words": "MIDDLE HIGH if Z >= 2.0, NOT SEEN if Z < 1.0, UNDECIDED between"},
                    "numpy": np.__version__, "python": sys.version.split()[0]},
           "hashes": hashes, "hash_ok_per_job": ok, "counts_copies": {}, "jobs": {}}
    pub = published_from_counts()
    present = [k for k in KEYS if (OUT / f"counts-t18-{k}.json").exists()]
    for key in present:
        cc = counts_copy_check(key)
        out["counts_copies"][key] = cc
        if not ok[key] or not cc["pass"]:
            out["jobs"][key] = {"note": "STOP: a file's SHA-256 differs from its record before analysis; this job is not read"}
            continue
        job = R15.read_monitor(key, f"t18/shots-t18-{key}.npz", f"t18/counts-t18-{key}.json", "ibm_fez")
        if "qubits" in job:
            w, ws = R15.job_word(job)
            job["job_word"], job["separable_span_words"] = w, ws
        out["jobs"][key] = job
        print(key, "counts check", job["counts_check"]["pass"], "word", job.get("job_word"), flush=True)
    read = [k for k in present if "qubits" in out["jobs"][k]]
    out["boundaries"] = []
    for key in read:
        out["boundaries"] += R15.boundary_rows(out["jobs"][key], pub)
    rows = []
    for a_, b_ in zip(read[:-1], read[1:]):
        js, rr = R15.between_jobs({"t11-job2": out["jobs"][a_], "t11-job3": out["jobs"][b_]})   # test 15's code; its keys relabelled
        lab = {"t11-job2": a_, "t11-job3": b_}
        for x in js:
            x["job"] = lab[x["job"]]
        for r in rr:
            r["jobs"] = [a_, b_]
            rows.append(r)
        out.setdefault("between_jobs_job_rows", {}).update({x["job"]: x for x in js})
    out["between_jobs"] = rows
    # section 5
    mrows = []
    for key in read:
        sr, n = span_rows_of(out["jobs"][key])
        mr = middle_job(key, sr, n)
        if True:   # ruling 3: for both jobs
            mr["beside_duty_by_span_index"] = [(i, r["span"], r["duty"], r["sd"]) for i, r in enumerate(sorted(sr, key=lambda r: r["t"]))]
        mrows.append(mr)
    out["middle_test"] = {"jobs": mrows, "pooled": pooled(mrows), "beside_test17": test17_Z()}
    jm, rm = this_run_means(out, read)
    out["beside_section4"] = {"label": "beside, no word", "this_run_jobs": jm, "this_run": rm, "earlier_monitor_jobs_17_and_19_October": earlier_monitor_means(),
                              "finding_30_run_means": FINDING_30, "gap_between_the_jobs": gap_between(read)}
    out["meta"]["elapsed_s"] = time.time() - t0
    (OUT / a.out).write_text(json.dumps(out))
    summary = {"words": {k: v.get("job_word") for k, v in out["jobs"].items()},
               "boundaries": [(b["job"], b["spans"], b["word"], round(b.get("ratio", float("nan")), 3)) for b in out["boundaries"]],
               "between": [(r["jobs"], r.get("word"), r.get("ratio")) for r in rows],
               "middle": {"jobs": [(r["job"], r.get("contributes"), r.get("C"), r.get("sd"), r.get("reason")) for r in mrows], "pooled": out["middle_test"]["pooled"]},
               "beside_means": {"jobs": [(r["job"], r["job_mean_w_duty"], r["job_sd"]) for r in jm], "run": rm}, "gap": out["beside_section4"]["gap_between_the_jobs"]}
    print(json.dumps(summary, indent=1, default=str))


if __name__ == "__main__":
    main()

